import assert from 'node:assert/strict';
import {createInitial} from '../../../lib/fixtures.ts';
import {apply,actions,entity,latest,canSee,notices} from '../../../lib/workflow.ts';
const now=new Date('2026-09-12T10:00:00+08:00'), due='2026-09-15T10:00:00+08:00';
let n=0;
const start=()=>createInitial(now), as=(s,identity)=>({...s,identity});
const run=(s,id,action,input={},time=now)=>apply(s,{id,action,rev:entity(s,id).rev,requestId:`audit-${++n}`,input:{note:'本轮评估所用合成证据说明',owner:'Q01',dueAt:due,evidence:[2],...input}},time);
const out=[];
function record(id,title,fn){try{out.push({id,title,reproduced:true,...fn()});}catch(e){out.push({id,title,reproduced:false,error:e.message});}}
function verification(count=2){let s=run(start(),'WO-1039','publish',{remedy:true,goal:'改进服务说明',standard:'完成说明且无消极表达',sampleCount:count,observation:'同业务整改后样例'}),id=s.remedies.at(-1).id;s=run(as(s,'A1048'),id,'accept_remedy');s=run(s,id,'sample_calls');s=run(s,id,'material',{samples:[s.calls.at(-1).id]});return[s,id];}
record('E01','补件可以指派给无法查看该通话的另一坐席',()=>{let s=run(start(),'F-1041','supplement',{owner:'A1186'}),sp=s.supplements.at(-1),a=as(s,'A1186');assert.equal(canSee(a,sp.id),false);return{supplement:sp.id,executor:sp.executor,visible:canSee(a,sp.id),actions:actions(a,sp.id),inTodo:notices(a).some(x=>x.id===sp.id)};});
record('E02','整改待补样例只能回复文字，无法追加样例关联',()=>{let[s,id]=verification();s=run(as(s,'Q01'),id,'verify',{value:'insufficient'});let sp=s.supplements.at(-1).id;s=run(as(s,'A1048'),id,'sample_calls');const newSample=s.calls.at(-1).id;const before=actions(s,id);assert.equal(before.includes('material'),false);s=run(s,sp,'reply',{samples:[newSample]});s=run(as(s,'Q01'),sp,'receive_supplement');let error='';try{run(s,id,'verify',{value:'pass'});}catch(e){error=e.message;}assert.match(error,/样例不足/);return{agentActions:before,sampleCreated:newSample,storedSamples:entity(s,id).materials.flatMap(m=>m.samples),passError:error};});
record('E03','主管确认时新选择的证据没有进入结论版本',()=>{let s=start(),r=entity(s,'WO-1039'),fid=r.findingIds[0],oldEvidence=entity(s,fid).evidence;s=run(s,r.id,'publish',{opinions:{[fid]:{value:'false_positive',note:'基于新的第四个片段改判',evidence:[3]}}});assert.deepEqual(entity(s,fid).evidence,oldEvidence);assert.equal(latest(entity(s,fid)).evidence,undefined);assert.notDeepEqual(entity(s,r.id).opinions[fid].evidence,[3]);return{selectedEvidence:[3],displayedEvidence:entity(s,fid).evidence,conclusion:latest(entity(s,fid)),originalOpinionEvidence:entity(s,r.id).opinions[fid].evidence};});
record('E04','整改失败退回下一轮时删除上一轮材料',()=>{let[s,id]=verification(1);const oldMaterials=entity(s,id).materials;s=run(as(s,'Q01'),id,'verify',{value:'fail'});s=run(as(s,'S01'),id,'return_remedy');assert.equal(entity(s,id).materials.length,0);return{previousMaterialCount:oldMaterials.length,currentMaterialCount:entity(s,id).materials.length,round:entity(s,id).round,acceptanceHistory:entity(s,id).acceptanceHistory.length};});
record('E05','进行中的申诉被补证入口新结论卡住',()=>{let s=start(),ap=entity(s,'AP-1033'),fid=ap.findingId;s=run(s,fid,'followup');s=run(s,fid,'dismiss',{value:'insufficient'});let error='';try{run(as(s,'A1048'),ap.id,'withdraw');}catch(e){error=e.message;}assert.match(error,/结论版本已变化/);assert.equal(entity(s,ap.id).status,'submitted');assert.ok(entity(s,'REC-1033').pause);return{latestVersion:latest(entity(s,fid)).version,appealVersion:entity(s,ap.id).conclusionVersion,appealStatus:entity(s,ap.id).status,withdrawError:error,remedyStillPaused:true};});
record('E06','同事实报错要求关联已有问题，但没有关联动作',()=>{let s=run(start(),'CALL-1040','spotcheck',{scope:'身份核验检查'}),r=s.reviews.at(-1),f=s.findings.find(x=>x.callId==='CALL-1040');let error='';try{run(as(s,'Q01'),r.id,'add_finding',{title:f.title,ruleId:f.ruleId});}catch(e){error=e.message;}assert.match(error,/关联已有问题/);const allowed=actions(as(s,'Q01'),r.id);assert.ok(!allowed.some(x=>/link|associate/.test(x)));return{error,allowedActions:allowed};});
record('E07','复核退回修改期限未保留已经发生的逾期',()=>{let s=start(),r=entity(s,'WO-1039'),oldDue=r.dueAt,time=new Date(Date.parse(oldDue)+60000);s=run(s,r.id,'return_review',{},time);assert.equal(entity(s,r.id).firstOverdueAt,undefined);return{oldDue,newDue:entity(s,r.id).dueAt,operatedAt:time.toISOString(),firstOverdueAt:entity(s,r.id).firstOverdueAt??null};});
record('E08','质检员当前复核没有补证申请动作',()=>{let s=as(start(),'Q01');const allowed=actions(s,'WO-1038');assert.ok(!allowed.some(x=>/supplement|request/.test(x)));return{allowedActions:allowed};});
record('E09','通话未结束仍可发布正式结论',()=>{let s=start();s=run(s,'F-1041','assign');const r=s.reviews.at(-1),fid=r.findingIds[0];s=run(as(s,'Q01'),r.id,'submit_review',{opinions:{[fid]:{value:'risk',note:'尚未结束通话的核查意见',evidence:[2]}}});s=run(as(s,'S01'),r.id,'publish',{remedy:false,noRemedy:'当前通话中已主动纠正'});assert.equal(entity(s,'CALL-1041').endedAt,undefined);assert.equal(entity(s,r.id).status,'done');return{callEnded:false,reviewStatus:entity(s,r.id).status,formalConclusion:latest(entity(s,fid)).value};});
console.log(JSON.stringify({version:'v0.1.0-mvp-p0',commit:'6f89f5a',testedAt:'2026-09-12',note:'Known-gap reproduction against isolated in-memory fixtures; no app state or source changed.',cases:out},null,2));
if(out.some(x=>!x.reproduced))process.exitCode=1;
